import { useState, useEffect } from 'react';
import { Handle, Position } from 'reactflow';
import { BaseNode } from './BaseNode';
import { Type } from 'lucide-react';

const VAR_REGEX = /\{\{\s*([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\}\}/g;
const extractVars = (text) => {
  const vars = [], seen = new Set();
  let m; VAR_REGEX.lastIndex = 0;
  while ((m = VAR_REGEX.exec(text)) !== null) {
    if (!seen.has(m[1])) { seen.add(m[1]); vars.push(m[1]); }
  }
  return vars;
};

const MIN_W = 230, CHAR_W = 7.5, LINE_H = 20, PAD = 48;

export const TextNode = ({ id, data }) => {
  const [text, setText] = useState(data?.text || '{{input}}');
  const [vars, setVars] = useState([]);
  const [width, setWidth] = useState(MIN_W);
  const [height, setHeight] = useState(64);

  useEffect(() => {
    const lines = text.split('\n');
    const w = Math.max(MIN_W, Math.max(...lines.map(l => l.length)) * CHAR_W + PAD);
    const h = Math.max(64, lines.length * LINE_H + 16);
    setWidth(w);
    setHeight(h);
    setVars(extractVars(text));
  }, [text]);

  const handleStyle = {
    width: 8, height: 8,
    background: '#0a0a0f',
    border: '2px solid #f59e0b',
    borderRadius: '50%',
    position: 'absolute',
    left: -4,
    cursor: 'crosshair',
  };

  return (
    <div style={{ position: 'relative' }}>
      <BaseNode id={id} title="Text" accentColor="#f59e0b" Icon={Type}
        outputs={[{ id: 'output', label: 'output' }]}
        style={{ minWidth: width }}>
        <textarea
          value={text}
          onChange={e => setText(e.target.value)}
          style={{
            width: '100%',
            height,
            background: '#0a0a0f',
            border: '1px solid #2a2a3a',
            borderRadius: 6,
            color: '#e8e8f0',
            fontSize: 12,
            padding: '5px 8px',
            outline: 'none',
            boxSizing: 'border-box',
            resize: 'none',
            lineHeight: 1.6,
            fontFamily: "'JetBrains Mono', monospace",
            transition: 'height 0.1s ease, border-color 0.15s',
          }}
        />
        {vars.length > 0 && (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, marginTop: 6 }}>
            {vars.map(v => (
              <span key={v} style={{
                fontSize: 10,
                background: '#f59e0b15',
                border: '1px solid #f59e0b40',
                borderRadius: 4,
                padding: '2px 6px',
                color: '#f59e0b',
                fontFamily: "'JetBrains Mono', monospace",
                fontWeight: 500,
              }}>
                {`{{${v}}}`}
              </span>
            ))}
          </div>
        )}
      </BaseNode>

      {vars.map((v, i) => (
        <div key={v} style={{
          position: 'absolute',
          top: `${vars.length === 1 ? 50 : ((i + 1) / (vars.length + 1)) * 100}%`,
          left: 0,
          transform: 'translateY(-50%)',
          pointerEvents: 'none',
        }}>
          <Handle type="target" position={Position.Left} id={`${id}-var-${v}`}
            style={{ ...handleStyle, pointerEvents: 'all' }} />
          <span style={{
            position: 'absolute',
            left: 10,
            top: 0,
            transform: 'translateY(-50%)',
            fontSize: 10,
            color: '#f59e0b99',
            fontWeight: 500,
            whiteSpace: 'nowrap',
            userSelect: 'none',
          }}>{v}</span>
        </div>
      ))}
    </div>
  );
};
